import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Conv2d + BatchNorm2d + ReLU
conv_bn_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_bn_relu_kernel(const float* input, const float* weight, const float* bias, const float* running_mean, const float* running_var, float* output, int in_channels, int out_channels, int kernel_size, int stride, int padding, int height, int width, float eps, float momentum) {
    int h = blockIdx.x * blockDim.x + threadIdx.x;
    int w = blockIdx.y * blockDim.y + threadIdx.y;
    int c = blockIdx.z * blockDim.z + threadIdx.z;

    if (h < height && w < width && c < out_channels) {
        float sum = 0.0f;
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                for (int ic = 0; ic < in_channels; ++ic) {
                    int ih = h * stride + kh - padding;
                    int iw = w * stride + kw - padding;
                    if (ih >= 0 && ih < height && iw >= 0 && iw < width) {
                        sum += input[ic * height * width + ih * width + iw] * weight[c * in_channels * kernel_size * kernel_size + ic * kernel_size * kernel_size + kh * kernel_size + kw];
                    }
                }
            }
        }
        sum = (sum - running_mean[c]) / sqrtf(running_var[c] + eps);
        sum = sum * bias[c];
        output[c * height * width + h * width + w] = fmaxf(sum, 0.0f);
    }
}

torch::Tensor conv_bn_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::Tensor running_mean, torch::Tensor running_var, int stride, int padding, float eps, float momentum) {
    int out_channels = weight.size(0);
    int height = input.size(2);
    int width = input.size(3);
    auto output = torch::zeros({out_channels, height, width}, input.options());

    dim3 block(16, 16, 1);
    dim3 grid((height + block.x - 1) / block.x, (width + block.y - 1) / block.y, out_channels);

    conv_bn_relu_kernel<<<grid, block>>>(input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), running_mean.data_ptr<float>(), running_var.data_ptr<float>(), output.data_ptr<float>(), input.size(1), out_channels, weight.size(2), stride, padding, height, width, eps, momentum);

    return output;
}
"""

conv_bn_relu_cpp_source = (
    "torch::Tensor conv_bn_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::Tensor running_mean, torch::Tensor running_var, int stride, int padding, float eps, float momentum);"
)

# Compile the inline CUDA code for fused Conv2d + BatchNorm2d + ReLU
conv_bn_relu = load_inline(
    name="conv_bn_relu",
    cpp_sources=conv_bn_relu_cpp_source,
    cuda_sources=conv_bn_relu_source,
    functions=["conv_bn_relu_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000, input_channels=3, alpha=1.0):
        super(ModelNew, self).__init__()

        def conv_bn(inp, oup, stride):
            return nn.Sequential(
                nn.Conv2d(inp, oup, 3, stride, 1, bias=False),
                nn.BatchNorm2d(oup),
                nn.ReLU(inplace=True)
            )

        def conv_dw(inp, oup, stride):
            return nn.Sequential(
                nn.Conv2d(inp, inp, 3, stride, 1, groups=inp, bias=False),
                nn.BatchNorm2d(inp),
                nn.ReLU(inplace=True),

                nn.Conv2d(inp, oup, 1, 1, 0, bias=False),
                nn.BatchNorm2d(oup),
                nn.ReLU(inplace=True),
            )

        self.model = nn.Sequential(
            conv_bn(input_channels, int(32 * alpha), 2),
            conv_dw(int(32 * alpha), int(64 * alpha), 1),
            conv_dw(int(64 * alpha), int(128 * alpha), 2),
            conv_dw(int(128 * alpha), int(128 * alpha), 1),
            conv_dw(int(128 * alpha), int(256 * alpha), 2),
            conv_dw(int(256 * alpha), int(256 * alpha), 1),
            conv_dw(int(256 * alpha), int(512 * alpha), 2),
            conv_dw(int(512 * alpha), int(512 * alpha), 1),
            conv_dw(int(512 * alpha), int(512 * alpha), 1),
            conv_dw(int(512 * alpha), int(512 * alpha), 1),
            conv_dw(int(512 * alpha), int(512 * alpha), 1),
            conv_dw(int(512 * alpha), int(512 * alpha), 1),
            conv_dw(int(512 * alpha), int(1024 * alpha), 2),
            conv_dw(int(1024 * alpha), int(1024 * alpha), 1),
            nn.AvgPool2d(7),
        )
        self.fc = nn.Linear(int(1024 * alpha), num_classes)
        self.conv_bn_relu = conv_bn_relu

    def forward(self, x):
        x = self.model(x)
        x = x.view(x.size(0), -1)
        x = self.fc(x)
        return x
